function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('#save').onclick=()=>{download(new Blob([JSON.stringify(patch,null,2)],{type:'application/json'}),'pixel-rave-modular-'+patch.genre+'.json');toast('Patch salvo com parâmetros, cabos e sequência.');};
$('#load').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>150000)throw new Error('Arquivo muito grande.');const next=JSON.parse(await file.text());if(!validatePatch(next))throw new Error('Abra um patch JSON do sintetizador modular (v2).');next.name=presets[next.genre].name;replacePatch(next);toast('Patch restaurado.');}catch(err){toast(err.message);}e.target.value='';};
$('#wav').onclick=async()=>{const b=$('#wav');b.disabled=true;b.textContent='RENDERIZANDO…';try{const blob=await exportWav(structuredClone(patch));download(blob,'pixel-rave-modular-'+patch.genre+'-'+patch.bpm+'bpm.wav');toast('WAV pronto: quatro compassos + cauda dos efeitos.');}catch(e){toast('Falha ao exportar: '+e.message);}finally{b.disabled=false;b.textContent='EXPORTAR WAV ↗';}};
